// RestaurantsServiceServer is the server API for RestaurantsService service.
// All implementations should embed UnimplementedRestaurantsServiceServer
// for forward compatibility.
type RestaurantsServiceServer interface {
	GetRestaurant(context.Context, *GetRestaurantRequest) (*GetRestaurantResponse, error)
	// Current menu of a restaurant: public data, no authorization (FR-216). A
	// restaurant without a menu is NOT_FOUND. Not a snapshot of a placed order.
	GetMenu(context.Context, *GetMenuRequest) (*GetMenuResponse, error)
	// Public data of up to 100 restaurants in one call for pages that show
	// restaurants of many items (ADR 7): no authorization. An unknown id is
	// absent from the response; the caller matches by restaurant_id, not by
	// position. Empty or more than 100 ids is INVALID_ARGUMENT.
	BatchGetRestaurants(context.Context, *BatchGetRestaurantsRequest) (*BatchGetRestaurantsResponse, error)
	// Current menus of up to 100 restaurants in one call (ADR 7): public data, no
	// authorization. A restaurant without a menu is absent from the response;
	// the caller matches by restaurant_id. Empty or more than 100 ids is
	// INVALID_ARGUMENT.
	BatchGetMenus(context.Context, *BatchGetMenusRequest) (*BatchGetMenusResponse, error)
	// Restaurants available for selection: public data, no authorization
	// (FR-205, FR-496). Open restaurants only unless include_closed; paged by a
	// cursor ordered by restaurant id.
	ListRestaurants(context.Context, *ListRestaurantsRequest) (*ListRestaurantsResponse, error)
	// Restaurants owned by the calling user, open and closed, paged by a cursor
	// ordered by restaurant id. Requires a user subject: restaurant#manage =
	// owner, so the owner filter is the authorization; a service subject is
	// PERMISSION_DENIED.
	ListOwnedRestaurants(context.Context, *ListOwnedRestaurantsRequest) (*ListOwnedRestaurantsResponse, error)
	// Command RPCs of the Order Fulfillment Workflow of orders, idempotent by order_id.
	ReceiveOrderRequest(context.Context, *ReceiveOrderRequestRequest) (*ReceiveOrderRequestResponse, error)
	CancelRestaurantOrder(context.Context, *CancelRestaurantOrderRequest) (*CancelRestaurantOrderResponse, error)
	// Moves an ACCEPTED scheduled order to the Kitchen Queue at its planned
	// start (FR-224); service identity of orders only. A repeat for a QUEUED
	// order succeeds without changes.
	QueueRestaurantOrder(context.Context, *QueueRestaurantOrderRequest) (*QueueRestaurantOrderResponse, error)
	// Delivery windows of scheduled orders (FR-673..FR-675, FR-695, FR-703).
	// ListScheduledSlots is public, like GetRestaurant. Reserve, Confirm and
	// Release are called by the service identity of orders.
	ListScheduledSlots(context.Context, *ListScheduledSlotsRequest) (*ListScheduledSlotsResponse, error)
	// A full window is a business result (slot_unavailable with alternatives);
	// a window off the grid, before now + MIN_LEAD, beyond the horizon or
	// outside the schedule is INVALID_ARGUMENT; a restaurant without settings
	// or not accepting orders now is FAILED_PRECONDITION
	// SCHEDULED_ORDERS_UNAVAILABLE. A repeat with the same order_id returns the
	// same reservation.
	ReserveScheduledSlot(context.Context, *ReserveScheduledSlotRequest) (*ReserveScheduledSlotResponse, error)
	ConfirmScheduledSlot(context.Context, *ConfirmScheduledSlotRequest) (*ConfirmScheduledSlotResponse, error)
	ReleaseScheduledSlot(context.Context, *ReleaseScheduledSlotRequest) (*ReleaseScheduledSlotResponse, error)
	// Kitchen commands of restaurant staff over one Restaurant Order addressed by
	// restaurant_id and restaurant_order_id. They require restaurant#operate_kitchen;
	// an order of another restaurant is NOT_FOUND, a forbidden transition is
	// FAILED_PRECONDITION. A repeated MarkRestaurantOrderReady succeeds without a
	// new fact; other repeats are FAILED_PRECONDITION.
	AcceptRestaurantOrder(context.Context, *AcceptRestaurantOrderRequest) (*AcceptRestaurantOrderResponse, error)
	RejectRestaurantOrder(context.Context, *RejectRestaurantOrderRequest) (*RejectRestaurantOrderResponse, error)
	// Starts the head of the Kitchen Queue of the restaurant (FR-225): the
	// kitchen does not choose the order. The head is a premium order or a
	// standard one waiting longer than the aging limit, then the other standard
	// ones, FIFO by queued_at inside a class. It assigns the free cook on line
	// with the earliest last assignment; without a free cook it is
	// RESOURCE_EXHAUSTED and the queue stays as it was. An empty queue starts
	// nothing: the response has no restaurant_order. A repeat with the same
	// request_id starts no other order and answers with the order the first
	// call started.
	StartNextPreparation(context.Context, *StartNextPreparationRequest) (*StartNextPreparationResponse, error)
	MarkRestaurantOrderAssembled(context.Context, *MarkRestaurantOrderAssembledRequest) (*MarkRestaurantOrderAssembledResponse, error)
	MarkRestaurantOrderReady(context.Context, *MarkRestaurantOrderReadyRequest) (*MarkRestaurantOrderReadyResponse, error)
	ReportPreparationDelay(context.Context, *ReportPreparationDelayRequest) (*ReportPreparationDelayResponse, error)
	ReportPreparationFailure(context.Context, *ReportPreparationFailureRequest) (*ReportPreparationFailureResponse, error)
	// Kitchen Queue of a restaurant (FR-583): Restaurant Orders in QUEUED in the
	// order recommended by the Kitchen Queue policy. Requires
	// restaurant#operate_kitchen. Orders in RECEIVED awaiting Acceptance are not
	// in the queue.
	GetKitchenQueue(context.Context, *GetKitchenQueueRequest) (*GetKitchenQueueResponse, error)
	// Incoming orders of a restaurant (FR-586): Restaurant Orders in RECEIVED
	// awaiting Accept or Reject, by ascending received_at, then by id. Requires
	// restaurant#operate_kitchen. An accepted order leaves this list.
	ListIncomingOrders(context.Context, *ListIncomingOrdersRequest) (*ListIncomingOrdersResponse, error)
	// Accepted scheduled orders waiting for their start, by planned_ready_at
	// (FR-684); requires restaurant#operate_kitchen.
	ListScheduledOrders(context.Context, *ListScheduledOrdersRequest) (*ListScheduledOrdersResponse, error)
	// Active orders of a restaurant's kitchen board: Restaurant Orders in
	// RECEIVED, QUEUED, PREPARING, ASSEMBLED and READY with their items, by
	// ascending received_at, then by id. Requires restaurant#operate_kitchen.
	// The recommended order of the QUEUED ones is GetKitchenQueue.
	ListActiveRestaurantOrders(context.Context, *ListActiveRestaurantOrdersRequest) (*ListActiveRestaurantOrdersResponse, error)
	// Restaurant administration. RegisterRestaurant requires platform#register_restaurant
	// and writes restaurant#owner; AssignStaff/RevokeStaff require restaurant#manage
	// and write restaurant#staff before saving. Staff commands are idempotent.
	RegisterRestaurant(context.Context, *RegisterRestaurantRequest) (*RegisterRestaurantResponse, error)
	// Name and premium fee of a restaurant (FR-202, FR-649); requires
	// restaurant#manage. Publishes no business fact.
	UpdateRestaurant(context.Context, *UpdateRestaurantRequest) (*UpdateRestaurantResponse, error)
	// Replaces the weekly opening hours (FR-696, FR-697); requires
	// restaurant#manage. Overlapping or empty intervals are INVALID_ARGUMENT.
	// Publishes no business fact.
	SetOpeningHours(context.Context, *SetOpeningHoursRequest) (*SetOpeningHoursResponse, error)
	// Settings of scheduled orders (FR-672); requires restaurant#manage.
	// Publishes no business fact.
	SetScheduledOrderSettings(context.Context, *SetScheduledOrderSettingsRequest) (*SetScheduledOrderSettingsResponse, error)
	AssignStaff(context.Context, *AssignStaffRequest) (*AssignStaffResponse, error)
	RevokeStaff(context.Context, *RevokeStaffRequest) (*RevokeStaffResponse, error)
	// Opening of a restaurant for new Restaurant Orders (FR-203). Both require
	// restaurant#manage and write RestaurantOpened/RestaurantClosed to the Outbox
	// in the same Unit of Work. A repeat succeeds with changed = false and no new
	// fact (AC-209). An unknown restaurant is NOT_FOUND.
	OpenRestaurant(context.Context, *OpenRestaurantRequest) (*OpenRestaurantResponse, error)
	CloseRestaurant(context.Context, *CloseRestaurantRequest) (*CloseRestaurantResponse, error)
	// Menu management (FR-210..FR-215). All require restaurant#manage_menu
	// (owner or staff). CreateMenu of a restaurant that has a menu is
	// ALREADY_EXISTS; a missing restaurant, menu or menu item is NOT_FOUND; an
	// invalid name or price is INVALID_ARGUMENT. AddMenuItem is not idempotent:
	// every call adds a new item. UpdateMenuItem and SetMenuItemAvailability
	// repeating the current values succeed with changed = false; a change of
	// availability writes MenuItemAvailabilityChanged to the Outbox.
	CreateMenu(context.Context, *CreateMenuRequest) (*CreateMenuResponse, error)
	AddMenuItem(context.Context, *AddMenuItemRequest) (*AddMenuItemResponse, error)
	UpdateMenuItem(context.Context, *UpdateMenuItemRequest) (*UpdateMenuItemResponse, error)
	SetMenuItemAvailability(context.Context, *SetMenuItemAvailabilityRequest) (*SetMenuItemAvailabilityResponse, error)
	// Cook Pool of a restaurant (FR-614..FR-616). Commands require
	// restaurant#manage_cooks (owner or staff); an unknown restaurant or a cook of
	// another restaurant is NOT_FOUND, an empty or longer than 64 characters name
	// is INVALID_ARGUMENT. A new cook is off line. Repeating the current line or
	// retirement succeeds with changed = false. TakeCookOffLine of a cook holding
	// a PREPARING or ASSEMBLED order and RetireCook of a cook on line are
	// FAILED_PRECONDITION; a retired cook cannot go on line (FAILED_PRECONDITION).
	// Every change pushes kitchenChanged of the restaurant (ADR 36).
	HireCook(context.Context, *HireCookRequest) (*HireCookResponse, error)
	PutCookOnLine(context.Context, *PutCookOnLineRequest) (*PutCookOnLineResponse, error)
	TakeCookOffLine(context.Context, *TakeCookOffLineRequest) (*TakeCookOffLineResponse, error)
	RetireCook(context.Context, *RetireCookRequest) (*RetireCookResponse, error)
	// Pool Load and cooks of a restaurant (FR-616). Requires
	// restaurant#view_orders.
	GetCookPool(context.Context, *GetCookPoolRequest) (*GetCookPoolResponse, error)
	// Demo Simulator (FR-604): state of the kitchen simulator of this service; both
	// require platform#operate_simulator, otherwise PERMISSION_DENIED.
	GetSimulator(context.Context, *GetSimulatorRequest) (*GetSimulatorResponse, error)
	SetSimulatorEnabled(context.Context, *SetSimulatorEnabledRequest) (*SetSimulatorEnabledResponse, error)
}

